<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventaires · PharmaCare</title><style>
:root{--o:#f57c00;--soft:#fff3e8;--ink:#24324a;--muted:#6b7280;--line:#e8edf3;--green:#22a447;--red:#e53935;--blue:#2563eb}*{box-sizing:border-box}body{margin:0;background:#f7f9fc;color:var(--ink);font-family:Inter,system-ui,sans-serif}.shell{margin-left:252px;padding:28px;min-height:100vh;overflow-x:clip}.hero,.head,.actions{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.title{display:flex;align-items:center;gap:15px}.icon{font-size:36px;padding:14px;border-radius:16px;background:var(--soft);color:var(--o)}h1{margin:0}.muted{color:var(--muted)}.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;margin-top:18px;box-shadow:0 8px 28px #24324a0a}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat strong{display:block;font-size:27px;margin-top:8px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:44px;border-radius:12px;padding:9px 14px;border:1px solid transparent;text-decoration:none;font-weight:800;cursor:pointer}.primary{background:var(--o);color:#fff}.outline{background:#fff;border:2px solid var(--o);color:var(--o)}.green{background:var(--green);color:#fff}.danger{background:#fff;border:2px solid #ffc4c4;color:var(--red)}input,select,textarea{width:100%;min-height:44px;padding:9px 11px;border:1px solid #d8e0e9;border-radius:11px;font:inherit;background:#fff}textarea{min-height:76px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:grid;gap:6px;font-weight:700}.full{grid-column:1/-1}.sheet-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}.message{background:#eaf8ef;color:#176b36;padding:12px 15px;border-radius:12px}.error{background:#fff0f0;color:var(--red)}.table-wrap{max-width:100%;overflow:auto}table{width:100%;border-collapse:collapse;min-width:980px}th,td{padding:11px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:#fafbfc}.badge{display:inline-block;padding:5px 9px;border-radius:99px;background:#eef7f1;color:var(--green);font-size:12px;font-weight:800}.badge.draft,.badge.counting{background:var(--soft);color:var(--o)}.badge.submitted{background:#eaf1ff;color:var(--blue)}.badge.rejected{background:#fff0f0;color:var(--red)}.inventory{border-left:4px solid var(--o)}.count-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1.5fr;gap:8px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line)}.positive{color:var(--green)}.negative{color:var(--red)}@media(max-width:900px){.shell{margin-left:0;padding:15px}.stats{grid-template-columns:1fr 1fr}.count-grid{grid-template-columns:1fr}}@media(max-width:560px){.stats,.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head><body>@include('components.app-sidebar')<main class="shell">
<header class="hero"><div class="title"><span class="icon material-symbols-outlined">inventory</span><div><h1>Inventaires physiques</h1><p class="muted">Comptage par lot, rapprochement, valorisation et ajustements traçables.</p></div></div>@if(auth()->user()->hasPermission('inventories.manage'))<button class="btn primary" data-sheet-open="inventory-create">+ Nouvel inventaire</button>@endif</header>
