<section class="stats"><article class="card stat"><span>Total</span><strong>{{ $inventories->count() }}</strong></article><article class="card stat"><span>En comptage</span><strong>{{ $inventories->where('status','counting')->count() }}</strong></article><article class="card stat"><span>À valider</span><strong>{{ $inventories->where('status','submitted')->count() }}</strong></article><article class="card stat"><span>Écart valorisé</span><strong>{{ number_format((float)$inventories->where('status','validated')->sum('variance_value'),2,',',' ') }}</strong></article></section>
