@elseif($inventory->lines->isNotEmpty())<div class="table-wrap"><table><thead><tr><th>Produit</th><th>Lot</th><th>Théorique</th><th>Physique</th><th>Écart</th><th>Valeur</th><th>Justification</th></tr></thead><tbody>@foreach($inventory->lines as $line)<tr><td>{{ $line->product?->name }}</td><td>{{ $line->batch?->batch_number }}</td><td>{{ $line->theoretical_quantity }}</td><td>{{ $line->physical_quantity }}</td><td class="{{ (float)$line->variance_quantity>=0?'positive':'negative' }}">{{ $line->variance_quantity }}</td><td>{{ number_format((float)$line->variance_value,2,',',' ') }}</td><td>{{ $line->justification ?: '—' }}</td></tr>@endforeach</tbody></table></div>@endif
@if($inventory->status==='submitted'&&auth()->user()->hasPermission('inventories.validate'))<div class="actions" style="margin-top:14px"><form method="post" action="{{ route('organizations.inventories.validate',[$organization,$inventory]) }}" onsubmit="return confirm('Valider et générer les ajustements de stock ?')">@csrf<input type="hidden" name="decision" value="approve"><button class="btn green">Valider et rapprocher</button></form><form method="post" action="{{ route('organizations.inventories.validate',[$organization,$inventory]) }}">@csrf<input type="hidden" name="decision" value="reject"><input name="rejection_reason" required minlength="5" placeholder="Motif du rejet"><button class="btn danger">Rejeter</button></form></div>@endif
@if($inventory->status==='validated')<p><strong>Valeur théorique :</strong> {{ number_format((float)$inventory->theoretical_value,2,',',' ') }} · <strong>Valeur physique :</strong> {{ number_format((float)$inventory->physical_value,2,',',' ') }} · <strong>Écart :</strong> {{ number_format((float)$inventory->variance_value,2,',',' ') }}</p>@elseif($inventory->status==='rejected')<p class="message error">{{ $inventory->rejection_reason }}</p>@endif</section>@empty<section class="card"><p>Aucun inventaire. Créez le premier inventaire de ce site.</p></section>@endforelse
